namespace sv_203b41f21e5246a692ba453e56ec8a68.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = [];
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        Add("Welcome to the notification center!");
        Add("Your profile was updated successfully.");
        Add("New comment on your post.");
    }

    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    public List<Notification> GetSince(int lastId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastId).ToList();
        }
    }

    private void Add(string message)
    {
        _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called by the polling loop to generate fake data.
    /// </summary>
    public void SimulateIncoming()
    {
        var messages = new[]
        {
            "You have a new follower!",
            "Your build succeeded.",
            "Deployment to production completed.",
            "New pull request review requested.",
            "Meeting reminder: standup in 10 minutes.",
            "Security alert: new sign-in detected.",
        };

        lock (_lock)
        {
            var msg = messages[Random.Shared.Next(messages.Length)];
            _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else
{
    <span class="badge bg-primary rounded-pill mb-3 d-inline-block fs-6">
        @notifications.Count notification@(notifications.Count != 1 ? "s" : "")
    </span>

    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(n => n.Id))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? notifications { get; set; }

    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        // ??= ensures we only load when state wasn't restored from prerender
        notifications ??= NotificationService.GetAll();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Only starts after the component is interactive — never during prerender
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        var lastId = notifications?.Count > 0
            ? notifications.Max(n => n.Id)
            : 0;

        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            // Simulate a new notification arriving on the server
            NotificationService.SimulateIncoming();

            var newer = NotificationService.GetSince(lastId);
            if (newer.Count > 0)
            {
                notifications ??= [];
                notifications.AddRange(newer);
                lastId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

