 @code {
     [PersistentState]
     public List<Notification>? notifications { get; set; }

     private CancellationTokenSource? _cts;

     protected override void OnInitialized()
     {
         // ??= ensures we only load when state wasn't restored from prerender
         notifications ??= NotificationService.GetAll();
     }

     protected override void OnAfterRender(bool firstRender)
     {
         if (firstRender)
         {
             // Only starts after the component is interactive — never during prerender
             _cts = new CancellationTokenSource();
             _ = PollForNotificationsAsync(_cts.Token);
         }
     }

     private async Task PollForNotificationsAsync(CancellationToken ct)
     {
         var lastId = notifications?.Count > 0
             ? notifications.Max(n => n.Id)
             : 0;

         while (!ct.IsCancellationRequested)
         {
             await Task.Delay(TimeSpan.FromSeconds(5), ct);

             // Simulate a new notification arriving on the server
             NotificationService.SimulateIncoming();

             var newer = NotificationService.GetSince(lastId);
             if (newer.Count > 0)
             {
                 notifications ??= [];
                 notifications.AddRange(newer);
                 lastId = newer.Max(n => n.Id);
                 await InvokeAsync(StateHasChanged);
             }
         }
     }

     public void Dispose()
     {
         _cts?.Cancel();
         _cts?.Dispose();
     }
 }

